package earth.terrarium.pastel.data.lang.guidebook.main;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class FusionShrineEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.fusion_shrine.page0.text", "To create [Black Shards](entry://general/onyx_shards) I developed a special construction.\\\nI can either click or throw items and buckets onto it. I can even process entire stacks of fusion ingredients at once, making fusing much more efficient than crafting a single item per cycle. Very useful for recipes that require good timing.");
		provider.add("book.pastel.guidebook.fusion_shrine.page1.text", "Either [#](bb00bb)Calcite[#]() or [#](bb00bb)Basalt[#]() will do.\\\nRequires a focus structure and clear view of the sky.");
		provider.add("book.pastel.guidebook.fusion_shrine.page2.text", "Dimensions: 9x9x5 blocks.");
		provider.add("book.pastel.guidebook.fusion_shrine.page3.text", "- 1 Fusion Shrine\n- 4 Polished Gemstone Blocks\n- 4 Chiseled Polished Blocks\n- 8 Polished Pillars\n- 12 Polished Slabs\n- 77 Polished Blocks\n\n\\\nI'm able to switch [#](bb00bb)Basalt[#]() with [#](bb00bb)Calcite[#]() and choose the [Gemstone Blocks](entry://decoration/gemstone_storage_blocks) to my liking, as always.");
	}
}
